// Fichier principal des interactions : appels au serveur, formulaires, tableaux et navigation.
const $ = id => document.getElementById(id);
const csrf = () => document.querySelector('meta[name="csrf-token"]')?.content || '';
let docs = [], tierData = [], accounts = [], notifications = [], currentUser = null, currentRole = 'admin';
let currentPage = 1, perPage = 20, lastDocument = null, currentArchiveCategory = '', confirmResolver = null, highlightedDocumentId = null;
let selectedDepositFiles = [];
let categories = ['Contrats','Factures','Courriers','RH','Interventions','Administration','Projets','Autre'];
let documentTypes = [], documentTypeCategories = {}, unreadNotificationCount = 0;
const roleLabel = role => ({admin:'Administrateur',assistante:'Assistante de direction',ceo:'CEO'}[role] || role);
const currentAccount = () => currentUser;
const allAccounts = () => accounts.length ? accounts : (currentUser ? [currentUser] : []);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// Fonction commune aux appels HTTP : ajoute le jeton CSRF, envoie la requête
// et transforme les réponses ou erreurs JSON en résultat exploitable par la page.
async function api(url, options={}) {
  const headers = {'Accept':'application/json','X-CSRF-TOKEN':csrf(), ...(options.headers||{})};
  const response = await fetch(url, {...options, headers, credentials:'same-origin'});
  const type = response.headers.get('content-type') || '';
  const body = type.includes('application/json') ? await response.json() : {};
  if (!response.ok) {
    if (response.status === 401) { showWelcome(); }
    const message = body.message || (body.errors ? Object.values(body.errors).flat().join(' ') : 'Une erreur est survenue.');
    throw new Error(message);
  }
  return body;
}
function run(task) { Promise.resolve(task).catch(error => showToast(error.message || 'Une erreur est survenue.')); }
function showToast(message) { const toast=$('toast'); if(!toast)return; toast.textContent=message; toast.style.display='block'; clearTimeout(window.toastTimer); window.toastTimer=setTimeout(()=>toast.style.display='none',3800); }
function showDepositError(message){$('depositErrorMessage').textContent=message||'Le document n’a pas pu être déposé. Vérifiez les informations et réessayez.';$('depositErrorModal').classList.remove('hidden');requestAnimationFrame(()=>$('depositErrorOk').focus());}
function runDeposit(){const button=$('depositSubmitButton');if(button?.disabled)return;const label=button?.textContent;if(button){button.disabled=true;button.textContent='Vérification et dépôt…';}Promise.resolve(deposit()).catch(error=>showDepositError(error.message||'Le dépôt a échoué.')).finally(()=>{if(button){button.disabled=false;button.textContent=label||'Déposer et traiter';}});}
// Affiche l’écran d’accueil et masque la connexion ainsi que l’application.
function showWelcome(){ $('welcome')?.classList.remove('hidden'); $('login')?.classList.add('hidden'); $('app')?.classList.add('hidden'); }
// Ouvre le formulaire de connexion depuis l’écran d’accueil.
function showLogin(){ $('welcome')?.classList.add('hidden'); $('login')?.classList.remove('hidden'); $('app')?.classList.add('hidden'); }
function showForgotPassword(){ $('forgotEmail').value=$('loginEmail').value.trim(); $('forgotResetResult').replaceChildren(); $('forgotPasswordModal').classList.remove('hidden'); }
async function requestPasswordReset(){const email=$('forgotEmail').value.trim();if(!email)return showToast('Saisissez une adresse e-mail.');const button=$('forgotPasswordModal').querySelector('.modal-actions .primary');button.disabled=true;button.textContent='Envoi…';try{const result=await api('/forgot-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});$('forgotResetResult').textContent=result.message;}catch(error){$('forgotResetResult').textContent=error.message||'Le mail de réinitialisation n’a pas pu être envoyé.';}finally{button.disabled=false;button.textContent='Envoyer le mail';}}
function togglePassword(id,button){ const input=$(id); input.type=input.type==='password'?'text':'password'; button.textContent=input.type==='password'?'Afficher':'Masquer'; button.setAttribute('aria-label',input.type==='password'?'Afficher le mot de passe':'Masquer le mot de passe'); }
function showPageError(message){ showToast(message); }

// Envoie les identifiants au serveur, charge les données de l’utilisateur connecté,
// puis affiche l’application avec les fonctionnalités correspondant à son rôle.
async function enterApp(){
  // Empêche un double envoi et indique que la vérification est en cours.
  const submit=$('loginForm').querySelector('[type="submit"]');submit.disabled=true;submit.dataset.originalText=submit.textContent;submit.textContent='Connexion…';
  try {
  // Transmet l’adresse e-mail et le mot de passe à Laravel au format JSON.
  const data=await api('/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('loginEmail').value.trim(),password:$('loginPassword').value})});
  // Actualise le jeton de sécurité et mémorise l’utilisateur ainsi que son rôle.
  if(data.csrf)document.querySelector('meta[name="csrf-token"]').content=data.csrf;
  currentUser=data.user; currentRole=currentUser.role; await loadWorkspace();
  // Après validation, masque les écrans publics et ouvre le tableau de bord autorisé.
  $('login').classList.add('hidden'); $('welcome').classList.add('hidden'); $('app').classList.remove('hidden');
  applyRole(); openPage('dashboard'); showToast(`Bienvenue ${currentUser.firstName} !`); startHeartbeat();
  } finally { // Réactive le bouton, y compris si le serveur refuse les identifiants.
    submit.disabled=false;submit.textContent=submit.dataset.originalText||'Se connecter →'; }
}
// Intercepte l’envoi HTML standard pour utiliser la connexion asynchrone et afficher l’erreur dans la page.
$('loginForm').addEventListener('submit',e=>{e.preventDefault();$('loginError').textContent='';enterApp().catch(error=>{$('loginError').textContent=error.message||'Connexion impossible.';showToast(error.message||'Connexion impossible.');});});
// Efface le message d’erreur dès que l’utilisateur corrige l’un des champs.
['loginEmail','loginPassword'].forEach(id=>$(id).addEventListener('input',()=>{$('loginError').textContent='';}));
// Restaure une session existante au rechargement de la page ; sinon revient à l’accueil.
async function restoreSession(){ try { const data=await api('/api/bootstrap'); currentUser=data.user; currentRole=currentUser.role; populate(data);setProfileForAccount(currentUser);updateAdminStats();renderAdminUsers(); $('welcome').classList.add('hidden'); $('login').classList.add('hidden'); $('app').classList.remove('hidden'); applyRole(); openPage('dashboard'); startHeartbeat(); } catch { showWelcome(); } }
async function loadWorkspace(){ const data=await api('/api/bootstrap'); populate(data); }
function populate(data){ currentUser=data.user; currentRole=currentUser.role; docs=data.documents||[]; tierData=data.tiers||[]; accounts=data.users||[currentUser]; notifications=data.notifications||[]; unreadNotificationCount=Number(data.unreadNotificationCount ?? notifications.filter(n=>!n.read).length); documentTypes=data.documentTypes||[];const savedCategories=Array.isArray(data.documentCategories)?data.documentCategories:categories;categories=[...new Map([...savedCategories,...docs.map(d=>d.category)].filter(c=>c&&c!=='—').map(c=>[String(c).trim().toLocaleLowerCase('fr'),String(c).trim()])).values()];refreshCategoryOptions();fillDocumentOptions(); const tierOptions=[...new Set(tierData.map(t=>t.name))];const tierSelect=$('dTier');if(tierSelect){const selected=tierSelect.value;tierSelect.innerHTML='<option value="">Veuillez s\u00e9lectionner un tiers</option>'+tierOptions.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');tierSelect.value=tierOptions.includes(selected)?selected:'';}const searchTier=$('docTier');if(searchTier){const selected=searchTier.value;searchTier.innerHTML='<option value="">Tous les tiers</option>'+tierOptions.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');searchTier.value=selected;}const recipients=data.recipients||[];const recipientSelect=$('recipient');if(recipientSelect){const selected=recipientSelect.value;recipientSelect.innerHTML='<option value="">Veuillez s\u00e9lectionner un destinataire</option>'+recipients.map(r=>`<option value="${r.id}">${esc(roleLabel(r.role))}</option>`).join('');recipientSelect.value=recipients.some(r=>String(r.id)===selected)?selected:'';}updateNotificationBadge();setProfileForAccount(currentUser); renderDocuments(); renderArchiveCategories(); renderTiers(); renderAdminUsers(); renderAllRecent(); renderCategoryPie(); renderAssistantUsageChart();renderAdminActivity();renderCeoConsultChart(); updateAdminStats(); renderNotifications(); }
const originalPopulate=populate;populate=function(data){documentTypeCategories=data.documentTypeCategories||{};const result=originalPopulate(data);renderPendingDocuments();return result;};
function setProfileForAccount(a){ if(!a)return; const full=a.name||[a.firstName,a.lastName].filter(Boolean).join(' '); ['topProfileName','profileName'].forEach(id=>{if($(id))$(id).textContent=full}); $('topProfileRole').textContent=roleLabel(a.role); $('profileRoleBadge').textContent=roleLabel(a.role); const values={profileEmail:a.email,profileLastName:a.lastName,profileFirstName:a.firstName,profilePhone:a.phone,profileFunction:a.function,profileAddress:a.address,profileNationality:a.nationality,profileRoleText:roleLabel(a.role)}; Object.entries(values).forEach(([id,value])=>{if($(id))$(id).textContent=value||'—'}); const photo=a.photo||''; document.querySelectorAll('.avatar,.profile-avatar').forEach(el=>{el.textContent=(a.firstName?.[0]||'')+(a.lastName?.[0]||''); el.style.backgroundImage=photo?`url("${photo}")`:'';el.style.backgroundSize='cover';el.style.backgroundPosition='center';el.style.color=photo?'transparent':'';}); updateProfilePresence(a); ['standardGreeting','ceoGreeting'].forEach(id=>{if($(id))$(id).textContent=`Bonjour, ${full||'utilisateur'}`}); }
// Affiche le tableau de bord et les éléments autorisés selon le rôle connecté.
function applyRole(){ const isAdmin=currentRole==='admin',isCEO=currentRole==='ceo'; document.querySelectorAll('[data-role]').forEach(el=>{const r=el.dataset.role;el.style.display=r==='admin'?(isAdmin?'':'none'):r==='assistante'?(isCEO?'none':''):''}); $('standardDashboard').classList.toggle('hidden',isAdmin||isCEO); $('adminDashboard').classList.toggle('hidden',!isAdmin); $('ceoDashboard').classList.toggle('hidden',!isCEO); $('profilePresence').style.display='inline-flex'; setProfileForAccount(currentUser); }
async function logout(){ const result=await api('/logout',{method:'POST'});if(result.csrf)document.querySelector('meta[name="csrf-token"]').content=result.csrf;clearInterval(window.heartbeat);currentUser=null;accounts=[];docs=[];showLogin();closeSidebar();showToast('Vous êtes déconnecté(e).'); }
$('logout').addEventListener('click',()=>run(logout()));
function startHeartbeat(){ clearInterval(window.heartbeat); if(currentUser){api('/api/heartbeat',{method:'POST'}).catch(()=>{});window.heartbeat=setInterval(()=>api('/api/heartbeat',{method:'POST'}).catch(()=>{}),20000);} }
async function refreshAdminStatuses(){if(currentRole!=='admin')return;const data=await api('/api/user-statuses');accounts=data.users||[];renderAdminUsers();renderAdminActivity();updateAdminStats();showToast('Statuts des utilisateurs actualisés.');}
// Branche les boutons de navigation sur la fonction qui change de page.
document.querySelectorAll('.main-nav button[data-page]').forEach(b=>b.addEventListener('click',()=>openPage(b.dataset.page)));
function openPage(id){const selected=id;if(id==='documents'){$('status').value='';$('documents').querySelector('.page-head h1').textContent='Documents';}document.querySelectorAll('.page').forEach(p=>p.classList.add('hidden')); $(id)?.classList.remove('hidden'); document.querySelectorAll('.main-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===selected)); if(id==='documents')renderDocuments(); if(id==='pending')renderPendingDocuments(); if(id==='archive')renderArchiveCategories(); if(id==='tiers')renderTiers(); if(id==='admin')renderAdminUsers(); if(id==='notifications')renderNotifications(); closeSidebar(); }
$('menu').onclick=()=>{ if(innerWidth<=780){const opened=$('sidebar').classList.toggle('open');$('backdrop').classList.toggle('show',opened);$('menu').setAttribute('aria-expanded',String(opened));}else{const collapsed=$('sidebar').classList.toggle('collapsed');$('menu').setAttribute('aria-expanded',String(!collapsed));} };
$('closeMenu').onclick=closeSidebar; $('backdrop').onclick=closeSidebar; function closeSidebar(){ $('sidebar').classList.remove('open');$('backdrop').classList.remove('show'); } window.addEventListener('resize',()=>{if(innerWidth<=780){$('sidebar').classList.remove('collapsed')}else closeSidebar()});
function roleLabelText(role){return roleLabel(role)}

function filteredDocs(){ const q=normalizeText($('docSearch')?.value||''),type=$('type')?.value||'',status=$('status')?.value||'',tier=$('docTier')?.value||'',date=$('dateFilter')?.value||''; return docs.filter(d=>{const text=normalizeText([d.name,d.tier,d.type,d.category].join(' '));const iso=(d.date||'').split('/').reverse().join('-');return (!q||text.includes(q))&&(!type||d.type===type)&&(!status||d.status===status)&&(!tier||d.tier===tier)&&(!date||iso===date)}); }
function renderDocuments(){ const body=$('body');if(!body)return; const list=filteredDocs(),pages=Math.max(1,Math.ceil(list.length/perPage));currentPage=Math.min(currentPage,pages);const start=(currentPage-1)*perPage; const rows=list.slice(start,start+perPage); body.innerHTML=rows.map(d=>{const pending=d.status==='En attente d’identification',target=Number(d.id)===Number(highlightedDocumentId);const rowClasses=[pending?'pending-document-row':'',target?'notification-target':''].filter(Boolean).join(' ');return `<tr data-document-id="${d.id}" class="${rowClasses}" ${pending?`onclick="openDocumentFromRow(event,${d.id})" onkeydown="openDocumentFromRowKey(event,${d.id})" tabindex="0" role="button" aria-label="Identifier ${esc(d.name)}"`:''}><td class="doc-name" title="${esc(d.name)}">${esc(d.name)}</td><td>${esc(d.type)}</td><td>${esc(d.category)}</td><td>${esc(d.tier)}</td><td>${esc(d.date)}</td><td><span class="status ${d.status==='Archivé'?'archived':'pending'}">${esc(d.status)}</span></td><td><div class="action-group"><button class="action-icon" title="Consulter" onclick="detail(${d.id})">◉</button>${currentRole==='ceo'?'':`${pending?`<button class="action-icon" title="Identifier" onclick="openIdentifyModal(${d.id})">✎</button>`:''}<button class="action-icon danger" title="Supprimer" aria-label="Mettre à la corbeille" onclick="deleteDocument(${d.id})">${trashIcon()}</button>`}</div></td></tr>`}).join('')||'<tr><td colspan="7" class="empty-row">Aucun document trouvé.</td></tr>'; $('docCount').textContent=list.length?`Affichage de ${start+1} à ${Math.min(start+perPage,list.length)} sur ${list.length} documents`:'Aucun document à afficher';renderPagination(pages); }
// Rafraichit la page dediee sans rediriger vers la liste generale des documents.
function renderPendingDocuments(){const body=$('pendingBody'),list=docs.filter(d=>d.status==='En attente d’identification');if(body)body.innerHTML=list.map(d=>`<tr class="pending-document-row" onclick="openIdentifyModal(${d.id})" onkeydown="openDocumentFromRowKey(event,${d.id})" tabindex="0" role="button" aria-label="Identifier ${esc(d.name)}"><td class="doc-name">${esc(d.name)}</td><td>${esc(d.type)}</td><td>${esc(d.tier)}</td><td>${esc(d.documentDate||'—')}</td><td><button class="action-icon" onclick="event.stopPropagation();openIdentifyModal(${d.id})" title="Identifier">✎ Identifier</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty-row">Aucun document en attente d’identification.</td></tr>';const count=$('pendingCount'),navCount=$('pendingNavCount');if(count)count.textContent=`${list.length} document${list.length>1?'s':''} en attente d’identification`;if(navCount){navCount.textContent=list.length;navCount.style.display=list.length?'':'none';}}
function openDocumentFromRow(event,id){if(event.target.closest('button,a,input,select,textarea'))return;const doc=docs.find(d=>d.id===id);if(!doc)return;if(doc.status==='En attente d’identification'&&['admin','assistante'].includes(currentRole)){openIdentifyModal(id);return;}detail(id);}
function openDocumentFromRowKey(event,id){if(event.key!=='Enter'&&event.key!==' ')return;event.preventDefault();openDocumentFromRow(event,id);}
function renderPagination(pages){let html=`<button ${currentPage===1?'disabled':''} onclick="changePage(${currentPage-1})">‹</button>`;for(let i=1;i<=pages;i++){if(pages>7&&i>3&&i<pages-2){if(i===4)html+='<span>…</span>';continue}html+=`<button class="${i===currentPage?'active':''}" onclick="changePage(${i})">${i}</button>`}html+=`<button ${currentPage===pages?'disabled':''} onclick="changePage(${currentPage+1})">›</button>`;$('pagination').innerHTML=html;}
function changePage(page){currentPage=page;renderDocuments();} ['docSearch','type','status','docTier','dateFilter'].forEach(id=>$(id)?.addEventListener(id==='docSearch'?'input':'change',()=>{currentPage=1;renderDocuments()}));
function toggleFilters(){$('advancedFilters').classList.toggle('hidden')} function clearFilters(){['docSearch','dateFilter'].forEach(id=>$(id).value='');['type','status','docTier'].forEach(id=>$(id).value='');currentPage=1;renderDocuments();}
function trashIcon(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3"/></svg>'}
function customConfirm(message,title='Confirmer la suppression'){ $('confirmTitle').textContent=title;$('confirmMessage').textContent=message;$('confirmModal').classList.remove('hidden');return new Promise(resolve=>confirmResolver=resolve); }
function resolveConfirm(value){$('confirmModal').classList.add('hidden');confirmResolver?.(value);confirmResolver=null;}
async function deleteDocument(id){const d=docs.find(x=>x.id===id);if(!d||!await customConfirm(`Supprimer « ${d.name} » ?`))return;await api(`/api/documents/${id}`,{method:'DELETE'});docs=docs.filter(x=>x.id!==id);renderDocuments();renderPendingDocuments();renderAllRecent();renderArchiveCategories();showToast('Document supprimé.');}
function openIdentifyModal(id){const doc=docs.find(d=>d.id===id);if(!doc)return;$('identifyDocumentId').value=id;$('identifyDocumentName').textContent=doc.name;const select=$('identifyType');select.innerHTML='<option value="">Sélectionnez le type</option>'+documentTypes.filter(t=>String(t).toLocaleLowerCase('fr')!=='autre').map(t=>'<option value="'+esc(t)+'">'+esc(t)+'</option>').join('');select.value='';$('identifyCategoryName').value='';$('identifyCategory').textContent='Choisissez une catégorie existante pour associer ce type, ou laissez vide si une catégorie est déjà associée.';select.onchange=()=>{$('identifyCategory').textContent=select.value?(mappedCategory(select.value)?'Catégorie actuelle : '+mappedCategory(select.value)+' — vous pouvez la modifier.':'Aucune catégorie associée : choisissez-en une pour enregistrer cette association.'):'Choisissez une catégorie existante ou déjà configurée.';};$('identifyModal').classList.remove('hidden');}
async function identifyDocument(){const id=$('identifyDocumentId').value,type=$('identifyType').value,category=$('identifyCategoryName').value.trim();if(!type&&!category)return showToast('Choisissez un type ou une catégorie pour identifier le document.');const payload={...(type?{type}:{}),...(category?{category}:{})};const result=await api('/api/documents/'+id+'/identify',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});Object.assign(documentTypeCategories,result.typeCategoryMapping||{});const i=docs.findIndex(d=>d.id===Number(id));if(i>=0)docs[i]=result.document;if(result.document.category&&result.document.category!=='—'&&!categories.includes(result.document.category))categories.push(result.document.category);refreshCategoryOptions();updateCategoryPreview();closeModal('identifyModal');renderDocuments();renderPendingDocuments();renderArchiveCategories();updateAdminStats();showToast(result.message);}
async function exportMonthlyDocuments(){const month=$('exportMonth').value;if(!month)return showToast('Choisissez le mois à exporter.');const response=await fetch(`/api/documents/export-month?month=${encodeURIComponent(month)}`,{credentials:'same-origin',headers:{'X-CSRF-TOKEN':csrf()}});if(!response.ok){const body=await response.json().catch(()=>({}));return showToast(body.message||'L’export mensuel a échoué.');}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`documents-${month}.zip`;link.click();URL.revokeObjectURL(url);}
function detail(id){const d=docs.find(x=>x.id===id);if(!d)return;lastDocument=d;openPage('detail');const ext=(d.ext||'').toLowerCase();const preview=['jpg','jpeg','png'].includes(ext)?`<img class="document-thumbnail" src="${esc(d.url)}" alt="Document">`:ext==='pdf'?`<iframe class="document-thumbnail pdf-thumbnail" src="${esc(d.url)}#page=1&toolbar=0&navpanes=0&scrollbar=0" title="Aperçu du document" scrolling="no" tabindex="-1"></iframe>`:`<div class="document-thumbnail generic-thumbnail"><span>${esc(d.ext||'DOC')}</span></div>`;$('detailBox').innerHTML=`<div><div class="preview-box">${preview}</div></div><div class="detail-info"><h2>${esc(d.name)}</h2>${[['Type',d.type],['Catégorie',d.category],['Tiers',d.tier],['Date du document',d.documentDate||'—'],['Date d’archivage',d.archivedAt||'En attente'],['Taille',d.size],['Statut',d.status],['Description',d.description||'—']].map(([l,v])=>`<div class="info-line"><small>${l}</small><b>${esc(v)}</b></div>`).join('')}<div class="detail-actions"><button class="primary" onclick="consultDocument(${d.id})">Consulter le document</button></div></div>`; }
async function consultDocument(id){const d=docs.find(x=>x.id===id);if(!d)return;const data=await api('/api/documents/'+id+'/consult',{method:'POST'});d.consultations=(d.consultations||0)+1;d.lastConsulted=new Date().toISOString();renderAllRecent();updateAdminStats();$('viewerContent').innerHTML=(d.mime||'').startsWith('image/')?'<img src="'+esc(data.url)+'" alt="'+esc(d.name)+'">':'<iframe src="'+esc(data.url)+'" title="'+esc(d.name)+'"></iframe>';$('documentViewer').classList.remove('hidden');document.body.classList.add('viewer-open');}
function closeDocumentViewer(){$('documentViewer').classList.add('hidden');document.body.classList.remove('viewer-open');$('viewerContent').innerHTML='';}
function downloadDocument(id){const d=docs.find(x=>x.id===id);if(d)window.location.assign(d.url+'?download=1');}

function selectionKey(file){return [(file.webkitRelativePath||file.name),file.size,file.lastModified].join('|');}
function handleSelection(fileList){const files=Array.from(fileList||[]);if(!files.length)return;const keys=new Set(selectedDepositFiles.map(selectionKey));for(const file of files){const key=selectionKey(file);if(!keys.has(key)){selectedDepositFiles.push(file);keys.add(key);}}renderSelectedFiles();}
function clearSelectedFiles(){selectedDepositFiles=[];filePicker.value='';folderPicker.value='';renderSelectedFiles();$('uploadTitle').textContent='Sélectionner des documents';$('uploadText').textContent='Choisissez des fichiers ou glissez-les ici.';}
function removeSelectedFile(index){selectedDepositFiles.splice(index,1);renderSelectedFiles();if(!selectedDepositFiles.length){$('uploadTitle').textContent='Sélectionner des documents';$('uploadText').textContent='Choisissez des fichiers ou glissez-les ici.';}}
function renderSelectedFiles(){const list=$('selectedFiles');if(!selectedDepositFiles.length){list.classList.add('hidden');$('removeSelectedFiles').classList.add('hidden');return;}list.classList.remove('hidden');$('removeSelectedFiles').classList.remove('hidden');$('uploadTitle').textContent='Fichiers sélectionnés';$('uploadText').textContent='Ajoutez ou retirez des fichiers avant de déposer.';list.innerHTML='<strong class="selected-files-title">Fichiers sélectionnés ('+selectedDepositFiles.length+')</strong>'+selectedDepositFiles.map((f,i)=>'<div class="selected-file"><span>'+esc(f.webkitRelativePath||f.name)+'</span><small>'+Math.max(1,Math.round(f.size/1024))+' Ko</small><button type="button" class="remove-one-file" onclick="removeSelectedFile('+i+')" aria-label="Retirer le fichier sélectionné">×</button></div>').join('');}
const filePicker=$('file'),folderPicker=$('folder'),drop=$('drop');
[filePicker,folderPicker].forEach(input=>input.addEventListener('change',()=>handleSelection(input.files)));
['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('dragging')}));
['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('dragging')}));
drop.addEventListener('drop',e=>handleSelection(e.dataTransfer.files));
async function deposit(){const files=currentDepositFiles();if(!files.length)return showDepositError('Aucun fichier n’a été retenu. Choisissez un document et vérifiez qu’il apparaît dans la liste avant de valider.');if($('dType').value==='__add_new__')return showDepositError('Ajoutez puis sélectionnez le type de document.');if(!$('docRef').value.trim()||!$('dTier').value||!$('recipient').value)return showDepositError('Renseignez la référence, le tiers et le destinataire.');const form=new FormData();files.forEach(f=>form.append('files[]',f,f.name));form.append('reference',$('docRef').value.trim());form.append('type',$('dType').value);form.append('tier',$('dTier').value);form.append('recipient_id',$('recipient').value);form.append('description',$('description').value);form.append('date_mode',$('dateMode').value);form.append('date_day',$('docDate').value);form.append('date_year',$('docYear').value);const result=await api('/api/documents',{method:'POST',body:form});docs.unshift(...result.documents);lastDocument=result.documents[0];renderDocuments();renderPendingDocuments();renderArchiveCategories();renderAllRecent();updateAdminStats();$('depositInfo').innerHTML=result.documents.map(d=>'<div class="info-row"><span>'+esc(d.name)+'</span><b>Type : '+esc(d.type)+' · Catégorie : '+esc(d.category)+' · Tiers : '+esc(d.tier)+' · Date du document : '+esc(d.documentDate||'—')+' · Archivage : '+esc(d.archivedAt||'En attente')+' · Taille : '+esc(d.size)+' · Statut : '+esc(d.status)+'</b></div>').join('');$('depositModal').classList.remove('hidden');resetDeposit();}
function currentDepositFiles(){return [...selectedDepositFiles];}
function resetDeposit(){filePicker.value='';folderPicker.value='';selectedDepositFiles=[];$('selectedFiles').classList.add('hidden');$('removeSelectedFiles').classList.add('hidden');$('selectedFiles').replaceChildren();$('docRef').value='';$('dType').value='';$('customType').value='';$('dTier').value='';$('recipient').value='';$('description').value='';$('dateMode').value='day';$('docDate').value=new Date().toISOString().slice(0,10);$('docYear').value='';$('docYear').classList.add('hidden');$('docDate').classList.remove('hidden');$('customTypeBox').classList.add('hidden');$('categoryPreview').textContent='Catégorie non définie : le document restera en attente d’identification.';$('uploadTitle').textContent='Sélectionner des documents';$('uploadText').textContent='Choisissez des fichiers ou glissez-les ici.';toggleDeleteTypeButton();}
function viewLastDocument(){closeModal('depositModal');if(lastDocument)detail(lastDocument.id)}

function normalizeText(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function renderArchiveCategories(){$('archiveCategories').innerHTML=categories.map(c=>{const count=docs.filter(d=>d.category===c&&d.status==='Archivé').length;return `<button class="archive-category" onclick="openArchiveCategory('${esc(c)}')"><div class="folder-icon">▱</div><h3>${esc(c)}</h3><p>Archives classées par mois</p><strong>${count} <small>documents</small></strong></button>`}).join('');}
function openArchiveCategory(category){currentArchiveCategory=category;$('archiveCategories').classList.add('hidden');$('archiveFolder').classList.remove('hidden');$('archiveTitle').textContent=category;clearArchiveFilters();$('archiveAdvancedFilters').classList.add('hidden');populateArchiveFilters();renderArchiveFolder();}
function closeArchiveFolder(){$('archiveFolder').classList.add('hidden');$('archiveCategories').classList.remove('hidden')}
function populateArchiveFilters(){const archived=docs.filter(d=>d.category===currentArchiveCategory&&d.status==='Archivé');const options=(id,values,label)=>{const el=$(id);if(!el)return;const selected=el.value;el.innerHTML='<option value="">'+label+'</option>'+[...new Set(values.filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr')).map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('');el.value=values.includes(selected)?selected:''};options('archiveType',archived.map(d=>d.type),'Tous les types');options('archiveTier',archived.map(d=>d.tier),'Tous les tiers');}
function toggleArchiveFilters(){$('archiveAdvancedFilters').classList.toggle('hidden')}
function clearArchiveFilters(){['archiveSearch','archiveDate','archiveType','archiveTier'].forEach(id=>{if($(id))$(id).value=''});}
function renderArchiveFolder(){const q=normalizeText($('archiveSearch').value),type=$('archiveType').value,tier=$('archiveTier').value,date=$('archiveDate').value;const list=docs.filter(d=>{const p=(d.date||'').split('/').map(Number),month=p.length===3?new Date(p[2],p[1]-1,1).toLocaleDateString('fr-FR',{month:'long'}):'',iso=p.length===3?String(p[2]).padStart(4,'0')+'-'+String(p[1]).padStart(2,'0')+'-'+String(p[0]).padStart(2,'0'):(d.date||'');return d.category===currentArchiveCategory&&d.status==='Archivé'&&(!type||d.type===type)&&(!tier||d.tier===tier)&&(!date||iso===date)&&(!q||normalizeText([d.name,d.reference,d.type,d.category,d.tier,d.date,month].join(' ')).includes(q))});$('archiveDocs').innerHTML='<div class="table-scroll"><table><thead><tr><th>Nom</th><th>Date</th><th>Tiers</th><th>Action</th></tr></thead><tbody>'+list.map(d=>'<tr><td>'+esc(d.name)+'</td><td>'+esc(d.date)+'</td><td>'+esc(d.tier)+'</td><td><button class="action-icon" onclick="detail('+d.id+')" aria-label="Consulter">&#9673;</button></td></tr>').join('')+(list.length?'':'<tr><td colspan="4" class="empty-row">Aucun document trouvé.</td></tr>')+'</tbody></table></div>';}
document.getElementById('archiveSearch').oninput=renderArchiveFolder;['archiveType','archiveTier','archiveDate'].forEach(id=>document.getElementById(id)?.addEventListener('change',renderArchiveFolder));

function renderTiers(){const q=normalizeText($('tierSearch').value),list=tierData.filter(t=>normalizeText([t.name,t.first,t.type,t.email].join(' ')).includes(q));$('tierGrid').innerHTML=list.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${esc(t.type)}</td><td>${esc(t.function||'—')}</td><td>${esc(t.phone||'—')}</td><td>${esc(t.email||'—')}</td><td><span class="${t.active?'active-badge':'inactive-badge'}">${t.active?'Actif':'Inactif'}</span></td><td><div class="action-group"><button class="action-icon" onclick="editTier(${t.id})" title="Modifier">✎</button><button class="text-btn" onclick="toggleTierStatus(${t.id})">${t.active?'Désactiver':'Activer'}</button></div></td></tr>`).join('')||'<tr><td colspan="7" class="empty-row">Aucun tiers enregistré.</td></tr>';}
$('tierSearch').oninput=renderTiers;
function openTierModal(id=null){$('tierModalTitle').textContent=id?'Modifier un tiers':'Ajouter un tiers';$('tierId').value=id||'';const t=tierData.find(x=>x.id===id);['tierName','tierFirst','tierFunction','tierAddress','tierPhone','tierEmail'].forEach(x=>$(x).value='');$('tierType').value='Client';if(t){$('tierName').value=t.name;$('tierFirst').value=t.first||'';$('tierFunction').value=t.function||'';$('tierType').value=t.type;$('tierAddress').value=t.address||'';$('tierPhone').value=t.phone||'';$('tierEmail').value=t.email||''}$('tierModal').classList.remove('hidden');}
function editTier(id){openTierModal(id)}
async function saveTier(){const id=$('tierId').value,obj={type_tiers:$('tierType').value,raison_sociale:$('tierName').value.trim(),nom:$('tierName').value.trim(),prenom:$('tierFirst').value.trim(),fonction:$('tierFunction').value.trim(),adresse:$('tierAddress').value.trim(),telephone:$('tierPhone').value.trim(),email:$('tierEmail').value.trim()};const data=await api(id?`/api/tiers/${id}`:'/api/tiers',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(obj)});const saved=tierFromApi(data.tier);if(id){const i=tierData.findIndex(t=>t.id===Number(id));if(i>=0)tierData[i]=saved;else tierData.push(saved)}else{const i=tierData.findIndex(t=>t.id===saved.id);if(i>=0)tierData[i]=saved;else tierData.push(saved)}closeModal('tierModal');renderTiers();showToast(data.message||(id?'Tiers modifié.':'Tiers ajouté.'));}
async function toggleTierStatus(id){const t=tierData.find(x=>x.id===id);if(!t)return;const result=await api(`/api/tiers/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({type_tiers:t.type,nom:t.name,prenom:t.first||'',raison_sociale:t.name,fonction:t.function||'',adresse:t.address||'',telephone:t.phone||'',email:t.email||'',statut:t.active?'inactif':'actif'})});Object.assign(t,tierFromApi(result.tier));renderTiers();showToast(`Le statut du tiers est maintenant ${t.active?'actif':'inactif'}.`);}
function tierFromApi(t){return{id:t.id,name:t.raison_sociale||t.nom,first:t.prenom,type:t.type_tiers,function:t.fonction,address:t.adresse,phone:t.telephone,email:t.email,active:t.statut==='actif'}}

function renderAllRecent(){const latest=docs.slice(0,4),consulted=docs.filter(d=>d.consultations>0).sort((a,b)=>String(b.lastConsulted||'').localeCompare(String(a.lastConsulted||''))).slice(0,4);const row=(d,i)=>`<div class="recent-item"><div class="file-icon ${i%2?'blue':''}"><span class="file-sheet"><span>${esc(d.ext)}</span></span></div><div><b>${esc(d.name)}</b><small>${esc(d.category)} · ${esc(d.tier)} · ${esc(d.date)}</small></div><button class="text-btn" onclick="detail(${d.id})">Consulter</button></div>`;['recent','adminRecent'].forEach(id=>{if($(id))$(id).innerHTML=latest.map(row).join('')||'<div class="empty-row">Aucun document récent.</div>'});if($('ceoRecent'))$('ceoRecent').innerHTML=consulted.map(row).join('')||'<div class="empty-row">Aucun document consulté récemment.</div>';}
function renderCategoryPie(){const totals={};docs.filter(d=>d.status==='Archivé').forEach(d=>totals[d.category]=(totals[d.category]||0)+1);const entries=Object.entries(totals),sum=entries.reduce((n,[,v])=>n+v,0);const colors=['#1455bd','#2878d0','#4599e5','#6bb9ef','#92d3f7','#2e6fb8','#3b87ca','#b3e2fa'];let start=0;const segments=entries.map(([name,count],i)=>{const end=start+(count/Math.max(sum,1))*100;const segment=`${colors[i%colors.length]} ${start}% ${end}%`;start=end;return{ name,count,color:colors[i%colors.length],segment};});const adminPie=$('adminCategoryPie'),adminLegend=$('adminCategoryLegend');if(adminPie)adminPie.style.background=segments.length?`conic-gradient(${segments.map(s=>s.segment).join(',')})`:'#e8eff7';if(adminLegend)adminLegend.innerHTML=segments.map(s=>`<div><i style="background:${s.color}"></i><span>${esc(s.name)}</span><b>${s.count}</b></div>`).join('')||'<span>Aucun document</span>';const donut=document.querySelector('#standardDashboard .donut'),assistantLegend=$('assistantCategoryLegend');if(donut)donut.style.background=segments.length?`conic-gradient(${segments.map(s=>s.segment).join(',')})`:'#e8eff7';if(assistantLegend)assistantLegend.innerHTML=segments.map(s=>`<div><i style="background:${s.color}"></i><span>${esc(s.name)}</span><b>${sum?Math.round(s.count/sum*100):0}%</b></div>`).join('')||'<span>Aucun document</span>';[adminLegend,assistantLegend].filter(Boolean).forEach(legend=>legend.querySelectorAll('div').forEach(item=>{item.style.cursor='pointer';item.onclick=()=>{const category=item.querySelector('span').textContent;openPage('documents');$('docSearch').value=category;renderDocuments()}}));}
function renderAssistantUsageChart(){const el=$('assistantUsageChart');if(!el)return;const names=['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Août','Sep','Oct','Nov','Déc'],year=new Date().getFullYear(),counts=Array(12).fill(0);docs.forEach(d=>{const p=d.date?.split('/').map(Number);if(p&&p[2]===year)counts[p[1]-1]++});const max=Math.max(...counts,1);el.innerHTML=counts.map((v,i)=>`<div class="chart-bar-wrap"><div class="chart-bar" style="height:${Math.max(v?8:2,v/max*100)}%" title="${v} documents"></div><span>${names[i]}</span></div>`).join('');}
function renderAdminActivity(){const el=$('adminActivityChart');if(!el)return;const roles=['admin','assistante','ceo'],palette=['#1455bd','#2878d0','#6bb9ef'],max=Math.max(1,...roles.map(r=>accounts.filter(a=>a.role===r&&a.presence).length));el.innerHTML=roles.map((role,i)=>{const n=accounts.filter(a=>a.role===role&&a.presence).length;return `<div class="chart-bar-wrap"><div class="chart-bar" style="height:${Math.max(3,n/max*100)}%;background:${palette[i]}" title="${n} en ligne"></div><span>${roleLabel(role).replace(' direction','')}</span></div>`}).join('');}
function renderCeoConsultChart(){const el=$('ceoConsultChart');if(!el)return;const names=['Jan','Fév','Mar','Avr','Mai','Juin','Juil','Août','Sep','Oct','Nov','Déc'],counts=Array(12).fill(0);docs.forEach(d=>{if(!d.lastConsulted)return;const dt=new Date(d.lastConsulted);if(dt.getFullYear()===new Date().getFullYear())counts[dt.getMonth()]++});const max=Math.max(...counts,1);el.innerHTML=counts.map((v,i)=>`<div class="bar-item"><span class="bar-value">${v||''}</span><div class="bar" style="height:${Math.max(v?6:1,v/max*90)}%" title="${v} consultation(s)"></div><span class="bar-label">${names[i]}</span></div>`).join('');}
function updateAdminStats(){const archived=docs.filter(d=>d.status==='Archivé').length,pending=docs.filter(d=>d.status==='En attente d’identification').length,newForCeo=docs.filter(d=>!Number(d.consultations||0)).length;if($('standardTotalCount'))$('standardTotalCount').textContent=docs.length;if($('standardArchivedCount'))$('standardArchivedCount').textContent=archived;if($('standardPendingCount'))$('standardPendingCount').textContent=pending;if($('assistantDocumentTotal'))$('assistantDocumentTotal').textContent=docs.length;if($('ceoReceivedCount'))$('ceoReceivedCount').textContent=docs.length;if($('ceoNewCount'))$('ceoNewCount').textContent=newForCeo;if($('ceoConsultedCount'))$('ceoConsultedCount').textContent=docs.filter(d=>d.consultations>0).length;if(!$('adminAccountCount'))return;const real=allAccounts();$('adminAccountCount').textContent=real.length;$('adminActiveCount').textContent=real.filter(u=>u.presence).length;$('adminNewDocsCount').textContent=newForCeo;$('adminArchivedCount').textContent=archived;$('adminPendingCount').textContent=pending;}
function renderAdminUsers(){if(!$('adminUsersTable'))return;$('adminUsersTable').innerHTML=accounts.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${roleLabel(u.role)}</td><td><span class="${u.presence?'active-badge':'inactive-badge'}">${u.presence?'En ligne':'Hors ligne'}</span></td><td>${u.role==='admin'?'<span class="protected-account">Compte protégé</span>':`<div class="user-actions"><button class="table-action edit" onclick="editAdminUser(${u.id})">Modifier</button><button class="table-action delete" onclick="deleteAdminUser(${u.id})" aria-label="Supprimer">${trashIcon()}</button></div>`}</td></tr>`).join('');updateAdminStats();renderAdminUsersSummary();}
function renderAdminUsersSummary(){const el=$('adminUsersSummary');if(!el)return;el.innerHTML=accounts.map(u=>`<div class="mini-user"><div class="mini-user-avatar">${u.presence?'●':'○'}</div><div><b>${esc(u.name)}</b><small>${roleLabel(u.role)}</small></div><span class="${u.presence?'active-badge':'inactive-badge'}">${u.presence?'En ligne':'Hors ligne'}</span></div>`).join('');}
function editAdminUser(id){const u=accounts.find(x=>x.id===id);if(!u||u.role==='admin')return;$('editUserEmail').value=u.id;$('editUserLastName').value=u.lastName||'';$('editUserFirstName').value=u.firstName||'';$('editUserEmailField').value=u.email;$('editUserRole').value=u.role;$('adminUserModal').classList.remove('hidden');}
async function saveAdminUserEdit(){const id=$('editUserEmail').value;const u=accounts.find(x=>x.id===Number(id));const data=await api(`/api/users/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({nom:$('editUserLastName').value,prenom:$('editUserFirstName').value,email:$('editUserEmailField').value,role:$('editUserRole').value})});Object.assign(u,data.user);closeModal('adminUserModal');renderAdminUsers();showToast('Compte mis à jour en base.');}
// Ajoute localement l'alerte renvoyée avec l'action, sans nouvel appel réseau.
function addOwnAdminNotification(notification){if(!notification)return;notifications.unshift(notification);if(!notification.read)unreadNotificationCount++;updateNotificationBadge();renderNotifications();}
async function deleteAdminUser(id){const u=accounts.find(x=>x.id===id);if(!u||!await customConfirm(`Supprimer le compte de ${u.name} ?`))return;try{const result=await api(`/api/users/${id}`,{method:'DELETE'});accounts=accounts.filter(x=>x.id!==id);addOwnAdminNotification(result.notification);renderAdminUsers();showToast(result.message||'Compte supprimé.');}catch(error){showToast(error.message||'La suppression du compte a échoué.');}}
async function createAdminUser(){const button=$('createUserButton');if(button?.disabled)return;const originalText=button?.textContent;if(button){button.disabled=true;button.textContent='Création…';}const body={nom:$('adminLastName').value.trim(),prenom:$('adminFirstName').value.trim(),email:$('adminEmail').value.trim(),telephone:$('adminPhone').value.trim(),adresse:$('adminAddress').value.trim(),password:$('adminPassword').value,role:$('adminRole').value};try{const data=await api('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});accounts.push(data.user);addOwnAdminNotification(data.notification);renderAdminUsers();['adminLastName','adminFirstName','adminEmail','adminPhone','adminAddress','adminPassword'].forEach(id=>$(id).value='');showToast(data.message||'Compte utilisateur créé.');}catch(error){showToast(error.message||'La création du compte a échoué.');}finally{if(button){button.disabled=false;button.textContent=originalText||'Créer le compte';}}
}

function mappedCategory(type){const key=String(type||'').trim().toLocaleLowerCase('fr');const entry=Object.entries(documentTypeCategories).find(([label])=>label.toLocaleLowerCase('fr')===key);return entry?categories.find(c=>c.toLocaleLowerCase('fr')===String(entry[1]).toLocaleLowerCase('fr'))||'':'';}
function updateCategoryPreview(){const category=mappedCategory($('dType')?.value);const el=$('categoryPreview');if(el)el.textContent=category?`Catégorie attribuée automatiquement : ${category}`:'Catégorie non définie : le document restera en attente d’identification.';}
function fillDocumentOptions(){const t=$('dType');if(t){const old=t.value,types=documentTypes.filter(v=>String(v).trim().toLowerCase()!=='autre');t.innerHTML='<option value="">Veuillez sélectionner un type</option>'+types.map(v=>'<option value="'+esc(v)+'">'+esc(v)+'</option>').join('')+'<option value="__add_new__">Ajouter un type</option>';t.value=types.includes(old)?old:(old==='__add_new__'?'__add_new__':'');}if($('docDate')&&!$('docDate').value)$('docDate').value=new Date().toISOString().slice(0,10);updateCategoryPreview();toggleDeleteTypeButton();}
function toggleCustomOption(kind){if(kind!=='type')return;const type=$('dType').value==='__add_new__';$('customTypeBox').classList.toggle('hidden',!type);updateCategoryPreview();toggleDeleteTypeButton();}
function toggleDeleteTypeButton(){const button=$('deleteSelectedType');if(button)button.classList.toggle('hidden',currentRole!=='admin'||!$('dType').value||$('dType').value==='__add_new__');}
async function deleteSelectedDocumentType(){const select=$('dType'),name=select.value;if(!name||currentRole!=='admin')return;if(!await customConfirm('Supprimer le type « '+name+' » ? Cette action est impossible si des documents l’utilisent.'))return;try{const result=await api('/api/document-options/type/'+encodeURIComponent(name),{method:'DELETE'});documentTypes=documentTypes.filter(type=>type!==result.name);fillDocumentOptions();showToast(result.message);}catch(error){showToast(error.message||'Le type n’a pas pu être supprimé.');}}
async function addDocumentOption(kind){const type=kind==='type',input=$(type?'customType':'customCategory'),name=input.value.trim();if(!name)return showToast('Saisissez un nom.');const data=await api(`/api/document-options/${kind}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});const list=type?documentTypes:categories;if(!list.includes(data.name))list.push(data.name);fillDocumentOptions();$(type?'dType':'dCategory').value=data.name;input.value='';toggleCustomOption(kind);showToast('Option ajout\u00e9e dans la liste.');}
function toggleDocumentDate(){const year=$('dateMode').value==='year';$('docDate').classList.toggle('hidden',year);$('docYear').classList.toggle('hidden',!year);}
function showProfileSettings(){ $('profileTab').classList.remove('hidden');$('securityTab').classList.add('hidden');document.querySelectorAll('.settings-tabs .tab').forEach((b,i)=>b.classList.toggle('active',i===0)); }
function showPasswordSettings(){ $('profileTab').classList.add('hidden');$('securityTab').classList.remove('hidden');document.querySelectorAll('.settings-tabs .tab').forEach((b,i)=>b.classList.toggle('active',i===1)); }
function openProfileEdit(){const a=currentUser;$('profileEditLastName').value=a.lastName||'';$('profileEditFirstName').value=a.firstName||'';$('profileEditPhone').value=a.phone||'';$('profileEditFunction').value=a.function||'';$('profileEditAddress').value=a.address||'';$('profileEditNationality').value=a.nationality||'';$('profileEditPhoto').value='';$('removeProfilePhoto').checked=false;$('profileEditModal').classList.remove('hidden');}
async function saveProfileEdit(){const form=new FormData();form.append('nom',$('profileEditLastName').value);form.append('prenom',$('profileEditFirstName').value);form.append('telephone',$('profileEditPhone').value);form.append('fonction',$('profileEditFunction').value);form.append('adresse',$('profileEditAddress').value);form.append('nationalite',$('profileEditNationality').value);form.append('remove_photo',$('removeProfilePhoto').checked?'1':'0');const photo=$('profileEditPhoto').files[0];if(photo)form.append('photo',photo);const data=await api('/api/profile',{method:'POST',body:form});currentUser=data.user;const index=accounts.findIndex(a=>a.id===currentUser.id);if(index>=0)accounts[index]=currentUser;setProfileForAccount(currentUser);renderAdminUsers();renderAdminUsersSummary();closeModal('profileEditModal');showToast('Informations du profil enregistrées.');}
async function changePassword(){await api('/api/password',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_password:$('oldPassword').value,password:$('newPassword').value,password_confirmation:$('confirmPassword').value})});['oldPassword','newPassword','confirmPassword'].forEach(id=>$(id).value='');showToast('Mot de passe modifié avec succès.');}
function updateProfilePresence(a){const el=$('profilePresence');if(!el)return;el.classList.toggle('offline',!a.presence);el.querySelector('.presence-label').textContent=a.presence?'En ligne':'Hors ligne';}
async function toggleProfilePresence(){const online=!currentUser.presence;const data=await api('/api/presence',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({online})});currentUser=data.user;setProfileForAccount(currentUser);if(online)startHeartbeat();else clearInterval(window.heartbeat);showToast(online?'Votre statut est maintenant en ligne.':'Votre statut est maintenant hors ligne.');}
function renderNotifications(){const list=$('notificationList');if(!list)return;list.innerHTML=notifications.map(n=>`<button type="button" class="notification notification-clickable ${n.read?'is-read':'is-unread'}" onclick="openNotification(${n.id})" aria-label="Marquer cette notification comme lue"><span class="notification-icon">${n.read?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>':'<span class="unread-bullet"></span>'}</span><span class="notification-message"><b>${esc(n.title||n.type)}</b><p>${esc(n.message||n.text)}</p></span><time>${esc(n.time||'')}</time>${n.read?'':'<span class="notification-unread-dot" aria-label="Non lu"></span>'}</button>`).join('')||'<div class="notification-empty">Aucune notification.</div>';updateNotificationBadge();}
async function markNotificationsRead(){await api('/api/notifications/read',{method:'POST'});notifications=notifications.map(n=>({...n,read:true}));unreadNotificationCount=0;renderNotifications();}
async function markNotificationRead(id){const notification=notifications.find(n=>Number(n.id)===Number(id));if(!notification||notification.read)return;await api(`/api/notifications/${id}/read`,{method:'POST'});notification.read=true;unreadNotificationCount=Math.max(0,unreadNotificationCount-1);renderNotifications();}
async function openNotification(id){const notification=notifications.find(n=>Number(n.id)===Number(id));if(!notification)return;if(!notification.read)await markNotificationRead(id);if(currentRole==='ceo'&&notification.documentId){const documentIndex=docs.findIndex(d=>Number(d.id)===Number(notification.documentId));if(documentIndex>=0){highlightedDocumentId=Number(notification.documentId);['docSearch','type','status','docTier','dateFilter'].forEach(field=>{if($(field))$(field).value='';});currentPage=Math.floor(documentIndex/perPage)+1;openPage('documents');requestAnimationFrame(()=>document.querySelector(`#body tr[data-document-id="${highlightedDocumentId}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}));clearTimeout(window.notificationHighlightTimer);window.notificationHighlightTimer=setTimeout(()=>{if(highlightedDocumentId===Number(notification.documentId)){highlightedDocumentId=null;renderDocuments();}},8000);return;}openPage('documents');showToast('Ce document n’est plus disponible dans votre liste.');}}
function updateNotificationBadge(){const count=unreadNotificationCount;const badge=$('notificationBadge');if(badge){badge.textContent=count;badge.classList.toggle('hidden',count===0);badge.setAttribute('aria-label',count+' notification(s) non lue(s)');}const nav=$('notificationNavCount');if(nav){nav.textContent=count;nav.style.display=count?'':'none';}}
function closeModal(id){$(id)?.classList.add('hidden');}
function closeDetail(){openPage('documents');}

window.addEventListener('load',restoreSession);
window.addEventListener('unhandledrejection',event=>{event.preventDefault();showToast(event.reason?.message||'Une erreur est survenue.');});
setInterval(()=>{if(!currentUser)return;if(currentRole==='admin')run(api('/api/user-statuses').then(data=>{accounts=data.users||[];renderAdminUsers();renderAdminActivity();updateAdminStats();}));run(api('/api/bootstrap').then(data=>{const page=document.querySelector('.page:not(.hidden)')?.id;populate(data);if(page)openPage(page)}));},15000);

function refreshCategoryOptions(){const list=$('identifyCategorySuggestions');if(!list)return;list.innerHTML=[...new Set(categories)].sort((a,b)=>a.localeCompare(b,'fr')).map(category=>'<option value="'+esc(category)+'"></option>').join('');}
